import {
  Form,
  Detail,
  ActionPanel,
  Action,
  useNavigation,
  LaunchProps,
  Icon,
  Keyboard,
} from "@raycast/api";
import { useEffect, useState, useRef, useCallback } from "react";

const ENDPOINTS = [
  "http://air.tail97979c.ts.net:8080/chat/stream",
  "http://100.103.103.57:8080/chat/stream",
];

type Role = "user" | "secretary";
interface Turn {
  role: Role;
  text: string;
  ts: number; // epoch ms
}

interface AskArgs {
  question: string;
}

// ---------------------------------------------------------------------------
// Plain-text conversation renderer (for Form.Description, which can't render markdown)
// ---------------------------------------------------------------------------

function fmtTime(ts: number): string {
  const d = new Date(ts);
  const h = d.getHours().toString().padStart(2, "0");
  const m = d.getMinutes().toString().padStart(2, "0");
  return `${h}:${m}`;
}

function renderHistoryPlain(turns: Turn[], inFlightStatus: string | null): string {
  const lines: string[] = [];
  for (const t of turns) {
    const who = t.role === "user" ? "You" : "Secretary";
    lines.push(`[${who} · ${fmtTime(t.ts)}]`);
    lines.push(t.text);
    lines.push("");
  }
  if (inFlightStatus) {
    lines.push("[Secretary · thinking]");
    lines.push(`(${inFlightStatus}…)`);
  }
  return lines.join("\n").trim() || "(new conversation)";
}

function renderHistoryMarkdown(turns: Turn[]): string {
  return turns
    .map((t) => {
      const header = t.role === "user" ? `### You · ${fmtTime(t.ts)}` : `### Secretary · ${fmtTime(t.ts)}`;
      return `${header}\n\n${t.text}`;
    })
    .join("\n\n---\n\n");
}

// ---------------------------------------------------------------------------
// Markdown viewer (push-navigated for rich rendering of replies)
// ---------------------------------------------------------------------------

function MarkdownView({ turns, thread }: { turns: Turn[]; thread: string | null }) {
  const lastReply = [...turns].reverse().find((t) => t.role === "secretary")?.text || "";
  return (
    <Detail
      markdown={renderHistoryMarkdown(turns)}
      navigationTitle="Secretary — markdown"
      metadata={
        <Detail.Metadata>
          <Detail.Metadata.Label title="Turns" text={`${turns.length}`} />
          {thread && <Detail.Metadata.Label title="Thread" text={thread} />}
        </Detail.Metadata>
      }
      actions={
        <ActionPanel>
          {lastReply && <Action.CopyToClipboard title="Copy Last Reply" content={lastReply} />}
          {thread && (
            <Action.OpenInBrowser
              title="Open Thread in Vault View"
              url={`http://air.tail97979c.ts.net:8080/secretary/agent-output/conversations/${thread}.md`}
            />
          )}
        </ActionPanel>
      }
    />
  );
}

// ---------------------------------------------------------------------------
// Main: Form-based chat (single view, history above, input below — Raycast AI shape)
// ---------------------------------------------------------------------------

export default function Ask(props: LaunchProps<{ arguments: AskArgs }>) {
  const { question } = props.arguments;

  const [turns, setTurns] = useState<Turn[]>([{ role: "user", text: question, ts: Date.now() }]);
  const [status, setStatus] = useState<string>("connecting");
  const [inFlight, setInFlight] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [thread, setThread] = useState<string | null>(null);
  const [duration, setDuration] = useState<number | null>(null);
  const [input, setInput] = useState<string>("");

  const cancelled = useRef(false);
  const initialFiredRef = useRef(false);
  // The Form.TextArea's id must change to force a remount when we want to clear it.
  // Raycast Forms don't reset controlled inputs reliably otherwise.
  const [inputKey, setInputKey] = useState<number>(0);
  const { push } = useNavigation();

  const runStream = useCallback(async (text: string, threadId: string | null) => {
    setInFlight(true);
    setError(null);
    setStatus("thinking");
    setDuration(null);

    const body = JSON.stringify(threadId ? { text, thread_id: threadId } : { text });
    let lastErr: string | null = null;

    for (const endpoint of ENDPOINTS) {
      try {
        const ctrl = new AbortController();
        const resp = await fetch(endpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body,
          signal: ctrl.signal,
        });
        if (!resp.ok || !resp.body) {
          lastErr = `HTTP ${resp.status} from ${endpoint}`;
          continue;
        }
        const reader = resp.body.getReader();
        const decoder = new TextDecoder();
        let buf = "";
        while (true) {
          if (cancelled.current) {
            ctrl.abort();
            return;
          }
          const { value, done: rDone } = await reader.read();
          if (rDone) break;
          buf += decoder.decode(value, { stream: true });
          const parts = buf.split("\n\n");
          buf = parts.pop() || "";
          for (const part of parts) {
            if (!part.trim()) continue;
            let evType = "message";
            let dataLine = "";
            for (const line of part.split("\n")) {
              if (line.startsWith("event: ")) evType = line.slice(7).trim();
              else if (line.startsWith("data: ")) dataLine = line.slice(6);
            }
            if (!dataLine) continue;
            let data: unknown;
            try {
              data = JSON.parse(dataLine);
            } catch {
              continue;
            }
            if (evType === "status") {
              const s = (data as { text?: string }).text;
              if (typeof s === "string") setStatus(s);
            } else if (evType === "result") {
              const r = data as { reply: string; thread: string; duration_s: number };
              setTurns((prev) => [...prev, { role: "secretary", text: r.reply || "(empty)", ts: Date.now() }]);
              if (r.thread) setThread(r.thread);
              if (typeof r.duration_s === "number") setDuration(r.duration_s);
              setInFlight(false);
            }
          }
        }
        return; // stream succeeded
      } catch (e) {
        lastErr = String((e as Error).message || e);
        continue;
      }
    }
    setError(lastErr || "all endpoints failed");
    setInFlight(false);
  }, []);

  const submit = useCallback(
    (text: string) => {
      const t = text.trim();
      if (!t || inFlight) return;
      setTurns((prev) => [...prev, { role: "user", text: t, ts: Date.now() }]);
      setInput("");
      setInputKey((k) => k + 1); // force TextArea remount → cleared
      runStream(t, thread);
    },
    [inFlight, runStream, thread],
  );

  useEffect(() => {
    cancelled.current = false;
    if (!initialFiredRef.current) {
      initialFiredRef.current = true;
      runStream(question, null);
    }
    return () => {
      cancelled.current = true;
    };
  }, [question, runStream]);

  const historyText = error
    ? `[Network error]\n${error}\n\nTried:\n${ENDPOINTS.map((e) => `  - ${e}`).join("\n")}\n\nIs Tailscale up? Is vault-view running on air?`
    : renderHistoryPlain(turns, inFlight ? status : null);

  return (
    <Form
      isLoading={inFlight && !error}
      navigationTitle={inFlight ? `Secretary — ${status}` : "Secretary"}
      actions={
        <ActionPanel>
          <Action.SubmitForm
            title={inFlight ? "Wait for Reply…" : "Send"}
            icon={Icon.ArrowUp}
            onSubmit={(values: { text?: string }) => submit(values.text || input)}
          />
          <Action.Push
            title="View as Markdown"
            icon={Icon.Document}
            shortcut={{ modifiers: ["cmd"], key: "m" } as Keyboard.Shortcut}
            target={<MarkdownView turns={turns} thread={thread} />}
          />
          {turns.length > 0 && (
            <Action.CopyToClipboard
              title="Copy Last Reply"
              icon={Icon.Clipboard}
              content={[...turns].reverse().find((t) => t.role === "secretary")?.text || ""}
              shortcut={{ modifiers: ["cmd"], key: "c" } as Keyboard.Shortcut}
            />
          )}
          {thread && (
            <Action.OpenInBrowser
              title="Open Thread in Vault View"
              icon={Icon.Globe}
              url={`http://air.tail97979c.ts.net:8080/secretary/agent-output/conversations/${thread}.md`}
              shortcut={{ modifiers: ["cmd"], key: "o" } as Keyboard.Shortcut}
            />
          )}
        </ActionPanel>
      }
    >
      <Form.Description title="Conversation" text={historyText} />
      <Form.TextArea
        key={`input-${inputKey}`}
        id="text"
        title="Message"
        placeholder={
          inFlight ? `(${status}… please wait)` : "type a follow-up, then ⌘↵ to send"
        }
        value={input}
        onChange={setInput}
        autoFocus
        enableMarkdown
      />
      {duration !== null && !inFlight && (
        <Form.Description title="Last reply" text={`${duration}s · thread ${thread || "?"}`} />
      )}
    </Form>
  );
}
